insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Jouer avec honnêteté','Ta balle bouge légèrement pendant que tu la cherches. Personne dans ton groupe ne l’a remarqué, mais toi, tu l’as vue bouger.','L’honnêteté commence précisément quand personne ne peut vérifier ton geste. Au golf, tu appliques toi-même les Règles, y compris les pénalités qui te concernent. Dire ce qui s’est passé permet au groupe de trouver la bonne procédure ; cela ne signifie pas qu’une pénalité s’applique forcément. Une décision transparente vaut plus qu’un score arrangé.','Arrête-toi, décris les faits sans les embellir et demande la procédure adaptée avant de jouer. Si tu ignores la règle, dis-le simplement. Note ensuite le score correspondant à la décision prise.','Se convaincre que « ce n’était presque rien » et jouer vite pour éviter d’en parler. Le silence laisse ensuite un doute sur la position de la balle et sur ton score.','Après une partie, raconte une décision que tu as prise avec honnêteté, même si personne d’autre ne l’avait remarquée.','Propose une situation ambiguë à l’entraînement et laisse le junior exposer les faits avant de discuter de la règle. Valorise la démarche honnête, pas seulement la réponse juridique.','R&A, Règles de golf, règles 1.2a et 1.3b','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
