insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Compter ses coups et ses pénalités','Sur un trou, tu joues depuis le départ, puis tu dois rejouer une balle. À l’arrivée au green, tu hésites sur le nombre de coups à annoncer.','Le score d’un trou comprend les coups joués et, selon la situation, les coups de pénalité. Reconstituer le trou dans l’ordre évite d’oublier un coup d’essai qui a réellement frappé la balle, un coup rejoué ou une pénalité. La procédure exacte dépend de ce qui est arrivé : demande de l’aide si tu n’es pas sûr.','Avant d’annoncer ton score, repasse mentalement du départ au trou. Compte chaque coup joué, ajoute les pénalités applicables, puis compare ton décompte avec celui de ton marqueur. En compétition, vérifie les scores trou par trou avant de rendre la carte.','Donner le chiffre qui « semble juste » sans refaire le trajet du trou. Une simple hésitation devient plus difficile à résoudre après la partie.','Sur un trou, explique calmement à ton marqueur comment tu arrives au total annoncé.','Fais raconter un trou fictif avec un dégagement puis un coup rejoué ; demande au junior de séparer coups joués, procédures et pénalités avant d’additionner.','R&A, Règles de golf, règles 1.3b et 3.3b','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
