insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Bien réagir après un mauvais coup','Ton approche finit dans un endroit difficile. Tu sens la colère monter alors que tes partenaires attendent leur tour.','Un mauvais coup fait partie du jeu et ne dit rien de ta valeur. Une réaction brusque peut gêner les autres, abîmer le terrain ou devenir dangereuse si le club est lancé. Revenir au calme t’aide aussi à choisir le prochain coup avec lucidité. Tu peux être déçu sans te défouler sur le matériel ou sur quelqu’un.','Pose ton club, éloigne-toi de la zone de jeu immédiate, respire lentement une fois et formule une consigne simple pour la suite : « je retrouve ma balle, puis je décide ». Si tu as besoin d’aide, parle-en au coach ou à ton groupe au bon moment.','Jeter le club, taper le sol ou accuser un partenaire. Ces gestes prolongent la frustration et peuvent mettre les autres en danger.','Essaie une courte routine de retour au calme après un coup raté et observe si elle t’aide à reprendre le jeu.','En séance, entraîne la routine sur un coup volontairement difficile, sans juger l’émotion exprimée. Interviens immédiatement si un geste présente un risque.','R&A, Règles de golf, règle 1.2a ; conseil pédagogique ActiviTee','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','good_practice'
from public.etiquette_cards where stable_key='01.3'
