insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Vérifier avant de jouer','Tu arrives sur ta balle près d’un chemin. Un jardinier travaille plus loin et un partenaire s’est arrêté à côté de toi.','Une balle, un club ou même un petit caillou peuvent blesser. Avant chaque coup, il faut regarder autour de la zone du swing et vers la trajectoire possible, y compris au-delà de la cible voulue. Le groupe précédent et le personnel d’entretien doivent être suffisamment éloignés. La sécurité passe avant l’envie de jouer vite.','Regarde derrière, à côté et devant toi. Vérifie que personne n’est à portée de ton club, puis que la zone où la balle pourrait partir est libre. Attends si un doute subsiste et demande au coach quand la visibilité est mauvaise.','Se fier uniquement à la direction dans laquelle on espère envoyer la balle. Un coup manqué peut partir nettement ailleurs.','Avant tes prochains coups, applique à voix basse ta vérification : autour de moi, trajectoire, groupe devant, entretien.','Fais varier la position de partenaires immobiles pendant un exercice sans balle et demande au junior de décider quand il peut jouer.','R&A, Règles de golf, règle 1.2a, sécurité des autres','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
