insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Crier « Fore ! »','Ta balle part vers des joueurs que tu n’avais pas vus à côté du fairway. Elle peut atteindre leur zone avant que tu puisses expliquer ce qui s’est passé.','L’alerte doit être immédiate et assez forte pour être entendue. « Fore ! » est le signal traditionnel qui prévient d’une balle dangereuse. Chercher d’abord à savoir si le coup était « vraiment mauvais » fait perdre de précieuses secondes. Prévenir n’efface pas la nécessité de vérifier avant le coup, mais peut aider les personnes exposées à se protéger.','Crie tout de suite « Fore ! » si ta balle risque de toucher quelqu’un, puis répète l’alerte si nécessaire. Avertis également ton groupe, attends que la situation soit sûre et suis les consignes de l’encadrement.','Rester silencieux par gêne ou murmurer seulement à son partenaire. Les personnes sur la trajectoire doivent recevoir l’avertissement.','Explique au coach quand tu donnerais l’alerte ; fais-le dans un exercice parlé, sans lancer de balle ni provoquer une fausse alerte.','Présente plusieurs trajectoires dessinées et demande au junior de désigner celles qui nécessitent l’alerte immédiate.','R&A, Règles de golf, règle 1.2a, avertissement de sécurité','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
from public.etiquette_cards where stable_key='02.2'
on conflict (card_id,version,locale) do nothing;
