insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Réagir lorsqu’une balle arrive vers soi','Tu entends « Fore ! » pendant que ton groupe traverse une zone ouverte. Tu ne sais pas encore d’où vient la balle.','Chercher la balle du regard peut te faire perdre le temps nécessaire pour te protéger. Le signal indique un risque immédiat, même si la trajectoire exacte est inconnue. Le réflexe précis est celui enseigné par l’encadrement pour le terrain et la situation : se protéger rapidement, sans courir vers une trajectoire possible.','Interromps ce que tu fais, protège ta tête et adopte sans attendre la position de protection apprise avec ton coach. Reste ainsi le temps que le danger soit passé. Ensuite seulement, vérifie que chacun va bien et suis les indications de l’encadrement.','Lever les yeux pour chercher la balle ou traverser le fairway au hasard. Ces réactions peuvent t’exposer davantage.','Répète le réflexe avec ton coach dans un exercice sans balle, puis explique pourquoi la protection vient avant la recherche visuelle.','Enseigne une consigne de protection courte et cohérente à tout le groupe ; fais une répétition sans balle dans un espace sûr.','R&A, Règles de golf, règle 1.2a ; consigne de sécurité de l’encadrement','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','club_guidance'
from public.etiquette_cards where stable_key='02.3'
on conflict (card_id,version,locale) do nothing;
