insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Arriver à l’heure','Ton départ est annoncé à 10 h 00. Tu franchis la porte du club à 9 h 59 avec ton sac encore à récupérer.','L’heure d’arrivée au club n’est pas l’heure à laquelle tu es prêt à jouer. En compétition, l’heure de départ est une donnée de jeu : il faut être prêt au point de départ à l’heure fixée, et la Règle 5.3a prévoit des conséquences en cas de retard. Hors compétition aussi, arriver préparé évite de mettre tout le groupe sous pression.','Prévois le trajet, l’accueil, les chaussures et l’échauffement. Fixe une heure d’arrivée qui te laisse une vraie marge. Avant de partir de chez toi, vérifie le lieu du départ et tout changement communiqué par l’organisateur.','Penser que se trouver sur le parking à l’heure indiquée suffit. Il reste parfois plusieurs étapes avant de pouvoir jouer.','Prépare un petit horaire pour ta prochaine partie, de l’arrivée au club jusqu’au moment où tu seras prêt au départ.','Fais comparer deux horaires réalistes, avec et sans marge. En compétition, montre où l’heure officielle est affichée.','R&A, Règles de golf, règle 5.3a','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
