insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Préparer son matériel','Au deuxième trou, tu découvres que tu n’as plus de balle de réserve et que ta gourde est restée au vestiaire.','Une préparation simple te rend autonome et évite les retours inutiles qui ralentissent ton groupe. Le contenu exact dépend de la météo, du parcours et de l’activité. L’idée n’est pas d’avoir un sac rempli, mais de disposer de ce dont tu auras réellement besoin sans gêner les autres.','La veille ou avant de partir, vérifie clubs, balles, tees, relève-pitch si nécessaire, eau et vêtements adaptés. Ajoute la carte de score ou le support demandé. Range les objets de façon à retrouver rapidement ce que tu cherches. Demande à l’encadrement ce qui est fourni.','Tout laisser au dernier moment et emprunter plusieurs objets en pleine partie. Cela peut interrompre le jeu et te distraire.','Prépare ton sac avec une checklist courte que tu pourras réutiliser avant la prochaine partie.','Demande au junior de bâtir sa propre liste selon une météo donnée. Vérifie l’autonomie sans imposer du matériel superflu.','Bonne pratique de préparation ActiviTee','Bonne pratique pédagogique ActiviTee ; relecture éditoriale requise','good_practice'
from public.etiquette_cards where stable_key='03.2'
