insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Lire les consignes locales','Avant la partie, tu vois un panneau sur une zone fermée et une annonce concernant l’interruption du jeu. Tu n’es pas sûr de ce qui s’applique aujourd’hui.','Les règles locales et les consignes d’un parcours complètent les Règles de golf dans un contexte précis. Certaines concernent le jeu ; d’autres concernent la sécurité ou l’accès aux zones. Elles peuvent changer selon l’état du terrain ou la compétition. Les ignorer risque de conduire à une mauvaise décision ou à un danger.','Lis les informations affichées ou communiquées pour ta partie. Repère les zones interdites, les signaux d’interruption et la personne à contacter en cas de doute. Si une consigne te paraît floue, demande avant de jouer plutôt que d’inventer une procédure.','Supposer que la consigne de la semaine précédente est toujours valable, ou confondre une règle locale avec une simple recommandation.','Identifie deux consignes affichées dans ton club et explique à qui tu demanderais une précision.','Montre où le club publie ses consignes et distingue avec le groupe une règle locale de jeu, une interdiction d’accès et une recommandation.','R&A, Règles de golf, règle 1.3a et règles locales du club','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','club_guidance'
from public.etiquette_cards where stable_key='03.3'
