insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Attendre sans gêner','Un partenaire se prépare à jouer depuis le départ. Tu attends avec ton sac près de lui et tu hésites sur l’endroit où te tenir.','Le bon emplacement répond à deux questions : es-tu hors de portée du club et d’une balle mal frappée, et ta présence risque-t-elle de distraire le joueur ? La réponse dépend de l’espace, de la direction du coup et des autres personnes. Un lieu confortable pour toi peut gêner celui qui joue.','Avant que le partenaire se place, recule vers une zone sûre et visible pour le groupe, sans te mettre dans sa ligne de jeu. Garde le matériel immobile. Si tu hésites, demande brièvement où te placer, puis laisse-lui l’espace nécessaire.','Se déplacer au dernier instant juste derrière le joueur ou tout près de sa balle. Même silencieux, un mouvement peut interrompre sa préparation.','Choisis ton emplacement avant qu’un partenaire ne commence sa préparation, puis vérifie qu’il te voit et qu’il est à l’aise.','Mets en scène plusieurs positions d’attente sans swing ni balle et fais expliquer les critères de sécurité et de discrétion.','R&A, Règles de golf, règle 1.2a, sécurité et considération','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
from public.etiquette_cards where stable_key='04.1'
on conflict (card_id,version,locale) do nothing;
