insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Respecter l’ordre de jeu et le ready golf','Sur le fairway, ta balle est plus proche du trou que celle d’un partenaire, mais tu es déjà prêt alors qu’il cherche son club.','L’ordre de jeu dépend de la formule. En stroke play, jouer prêt peut aider le rythme si c’est sûr et responsable ; les joueurs peuvent s’accorder pour le faire. En match play, l’ordre a un rôle différent et un adversaire peut demander qu’un coup joué hors tour soit annulé. Le ready golf n’autorise jamais à jouer vers quelqu’un.','Identifie d’abord la formule de jeu. Si le ready golf convient, annonce clairement que tu es prêt, vérifie que personne ne se trouve sur ta trajectoire et laisse le temps aux autres de s’écarter. En cas de doute, suis l’ordre prévu.','Croire que « je suis prêt » donne toujours priorité, y compris en match play ou quand un autre joueur se trouve devant.','Explique au coach un exemple de ready golf sûr et approprié en stroke play, puis ce qui changerait en match play.','Fais jouer verbalement deux scénarios, un en stroke play et un en match play, avant de laisser les juniors proposer l’ordre.','R&A, Règles de golf, règles 5.6b et 6.4','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
from public.etiquette_cards where stable_key='04.2'
on conflict (card_id,version,locale) do nothing;
