insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Replacer ou réparer un divot','Après ton coup depuis le fairway, un morceau de gazon s’est soulevé. Tu vois aussi une trace près de la balle encore en jeu d’un autre joueur.','Réparer le terrain aide les groupes suivants et l’entretien du parcours. La bonne méthode dépend du type de gazon et des consignes du club : on replace parfois le morceau, ailleurs on utilise un mélange. Avant d’agir près d’une balle encore en jeu, il faut éviter d’améliorer les conditions qui pourraient affecter un coup à venir.','Demande quelle méthode le club recommande. Répare la trace de ton coup après avoir quitté la zone où les joueurs doivent encore jouer, sans modifier la ligne ou l’environnement immédiat d’une balle en jeu. Si la situation est délicate, attends ou demande au coach.','Replacer mécaniquement de la terre sur une zone qu’un partenaire doit encore utiliser, ou laisser le divot sans vérifier la méthode locale.','Demande la méthode du club et répare correctement un divot dans une situation où aucun coup restant ne peut être amélioré.','Montre deux types de surface et rappelle la limite de la Règle 8 avant toute réparation près d’une balle encore à jouer.','R&A, Règles de golf, règles 1.2a et 8.1 ; consignes d’entretien du club','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
from public.etiquette_cards where stable_key='04.3'
on conflict (card_id,version,locale) do nothing;
