insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Être prêt à jouer','Tu attends ton tour sur le fairway. Quand les autres ont fini, tu commences seulement à chercher la distance et à choisir un club.','Une partie avance mieux lorsque chacun prépare son prochain coup pendant les moments disponibles. Cela ne signifie pas se précipiter dans la zone de swing d’un partenaire. Tu peux observer ta balle, estimer la distance et imaginer une option pendant que le groupe se déplace, puis faire ta routine sans retard inutile lorsque la voie est libre.','Entre deux coups, repère ta balle et la zone d’atterrissage souhaitée. Choisis une ou deux options de club pendant l’attente, sans faire de bruit ni te placer devant quelqu’un. Quand c’est ton tour, confirme la sécurité, puis joue.','Attendre d’être appelé pour commencer toute réflexion, ou préparer son coup en marchant dans la trajectoire d’un autre joueur.','Sur trois trous, anticipe ton choix de club pendant une attente sûre, puis note si tu étais prêt au bon moment.','Observe le temps de préparation sans chronométrer chaque junior. Donne une consigne concrète sur ce qui peut être préparé avant son tour.','R&A, Règles de golf, règle 5.6b, recommandations de cadence','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
from public.etiquette_cards where stable_key='05.1'
on conflict (card_id,version,locale) do nothing;
insert into public.etiquette_cards(theme_id,stable_key,position)
select id,'05.2',2 from public.etiquette_themes where stable_key='05'
