insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Rester au contact du groupe précédent','Ton groupe termine un trou et le départ suivant est libre. Vous continuez pourtant à discuter derrière le green pendant que le groupe devant s’éloigne.','Le rythme se juge surtout par la place que garde ton groupe sur le parcours. Prendre soin de son coup et avancer efficacement sont compatibles. Un groupe plus rapide derrière vous peut parfois passer, si les conditions et l’organisation du parcours le permettent. La décision se prend avec le groupe et selon les consignes du club.','Après le trou, quitte le green sans traîner et rejoins la zone du prochain départ. Observe l’écart avec le groupe devant. Si votre groupe perd durablement le contact, parle-en au coach ou au responsable ; suivez ensemble la procédure locale pour faciliter éventuellement un passage.','Regarder seulement le groupe derrière et accélérer en oubliant la sécurité, ou refuser tout passage sans tenir compte de l’écart devant.','Avec le coach, observe sur quelques trous où se trouve le groupe précédent et discute d’une action simple pour garder le rythme.','Aide les juniors à lire l’espace devant leur groupe et à distinguer attente normale, retard évitable et situation où un passage est adapté.','R&A, Règles de golf, règle 5.6b, recommandations de cadence','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
from public.etiquette_cards where stable_key='05.2'
on conflict (card_id,version,locale) do nothing;
