insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Chercher une balle sans bloquer le parcours','Une balle part dans une zone d’herbes hautes. Plusieurs joueurs marchent dans des directions différentes sans se souvenir de son point de chute.','Un repère visuel rend la recherche plus efficace. Selon la Règle 18.2a, une balle est perdue si elle n’est pas trouvée dans les trois minutes après le début de la recherche par le joueur ou son cadet. Ce délai réglementaire n’est pas une invitation à chercher longtemps avant d’organiser le groupe. D’autres procédures, dont une balle provisoire, peuvent dépendre de la situation.','Regarde la trajectoire jusqu’au sol et retiens un arbre, une borne ou une pente proche. Cherchez méthodiquement dans la zone probable, sans piétiner inutilement. Faites appel au coach si la balle n’est pas retrouvée et appliquez la procédure correcte avant de poursuivre.','Courir tous au hasard, perdre le repère initial ou continuer la recherche après le délai applicable en supposant que le score n’en sera pas affecté.','Suis visuellement une balle jouée par un partenaire et mémorise un repère de chute que tu pourras lui indiquer.','Utilise un exercice de trajectoire sans balle perdue pour travailler les repères, puis explique quand le délai de trois minutes commence.','R&A, Règles de golf, règles 18.2a et 18.3','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
from public.etiquette_cards where stable_key='05.3'
on conflict (card_id,version,locale) do nothing;
