insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Entrer au bon endroit','Ta balle repose au milieu d’un bunker. Le chemin le plus court passe par un bord abrupt et fragile.','Le bord d’un bunker peut s’effriter sous les chaussures et rendre la sortie dangereuse. Un accès légèrement plus long préserve la forme du terrain et évite de laisser des traces difficiles à réparer. Chaque bunker a sa géométrie ; il n’existe pas un point d’entrée identique partout.','Observe les accès possibles avant de descendre. Choisis un côté bas et stable si le terrain le permet, en restant attentif aux autres joueurs et aux balles. Rejoins ta balle par un trajet simple que tu pourras ratisser en repartant. Demande une autre solution si l’accès paraît glissant ou dangereux.','Sauter depuis le bord le plus haut pour gagner quelques pas. Cela peut endommager la lèvre du bunker et te faire perdre l’équilibre.','Avec ton coach, repère un accès approprié à un bunker d’entraînement et explique ton choix.','Fais comparer plusieurs accès depuis l’extérieur et prends en compte l’état du sable, le bord et la sécurité avant d’entrer.','R&A, Règles de golf, règle 1.2a, soin du parcours ; conseil d’entretien du club','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','good_practice'
from public.etiquette_cards where stable_key='06.1'
on conflict (card_id,version,locale) do nothing;
