insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Quitter le bunker sans l’endommager','Tu as bien ratissé la zone du coup, mais tu dois encore remonter par une pente fragile. Le râteau est posé à côté de la sortie.','Le soin du bunker continue jusqu’à ce que tu sois complètement sorti. Les derniers pas peuvent recréer des traces et un appui sur un bord fragile peut le casser. La place du râteau n’est pas universelle : elle dépend des consignes du club et parfois du dessin du bunker.','Reprends le chemin d’accès le plus stable. Ratisse les dernières empreintes au fur et à mesure, sors sans prendre appui sur la lèvre fragile, puis replace le râteau là où le club le demande. Depuis l’extérieur, regarde une dernière fois si ton passage est visible.','Quitter le bunker en laissant les dernières empreintes près de la sortie ou ranger le râteau à une place supposée valable partout.','Vérifie derrière toi l’état du bunker et la place du râteau selon la consigne locale.','Demande aux juniors où le club veut les râteaux et fais observer la sortie depuis l’extérieur avant de conclure l’exercice.','R&A, Règles de golf, règle 1.2a ; consignes d’entretien du club','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','club_guidance'
from public.etiquette_cards where stable_key='06.3'
on conflict (card_id,version,locale) do nothing;
