insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Relever un pitch','Ta balle tombe sur le green et laisse une petite marque. Plus loin, tu remarques un autre impact qui n’a pas été réparé.','Une marque d’impact non réparée peut gêner les putts suivants et abîmer durablement la surface. Le bon geste consiste à rapprocher doucement les bords de la marque selon la méthode enseignée par le club, sans soulever la terre du fond. La Règle 13.1c autorise la réparation de certains dommages sur le green, notamment les impacts de balle.','Repère la marque, utilise l’outil adapté et fais d’abord vérifier ton geste par un coach ou un adulte compétent. Travaille délicatement les bords vers le centre puis lisse avec le putter. Répare une autre marque seulement si tu peux le faire sans gêner le groupe ni retarder le jeu.','Soulever le centre de l’impact avec l’outil. Ce geste peut casser les racines et laisser une bosse plus difficile à réparer.','Fais vérifier ta technique, puis répare un impact supplémentaire sur un green où tu peux intervenir sans gêner le jeu.','Montre le geste sur une surface d’exercice et corrige la direction du mouvement avant de confier un impact réel au junior.','R&A, Règles de golf, règle 13.1c','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
