insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Respecter les lignes de jeu','Deux partenaires préparent leur putt. Pour rejoindre ta balle, le trajet le plus direct te ferait passer entre l’une de leurs balles et le trou.','Se déplacer devant quelqu’un qui vise ou projeter son ombre sur sa ligne peut le distraire. Le respect des lignes de jeu est surtout une question de considération et d’organisation. Il ne faut pas transformer cela en ancienne interdiction générale de toucher une ligne de putt : les Règles actuelles traitent plutôt les actions qui améliorent les conditions d’un coup.','Observe les balles, le trou et les joueurs avant de marcher. Contourne les lignes de putt lorsque c’est simple, reste immobile pendant leur préparation et déplace ton ombre si elle gêne. Demande où passer lorsque l’espace est réduit.','Traverser rapidement devant un joueur en pensant que la vitesse rend le passage invisible, ou annoncer à tort qu’un simple contact sur la ligne crée toujours une pénalité.','Choisis un trajet respectueux autour des lignes de putt de ton groupe et explique ton choix à un partenaire.','Dessine plusieurs lignes de putt et propose des déplacements possibles ; distingue discrétion et véritable amélioration des conditions de jeu.','R&A, Règles de golf, règles 1.2a, 8 et 13','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
