insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Manipuler le drapeau et protéger le trou','Ton groupe arrive sur le green. Un partenaire veut putter avec le drapeau en place, un autre envisage de le retirer.','La Règle 13.2 laisse des choix concernant le drapeau ; le groupe doit se coordonner avant chaque coup. Une manipulation brusque peut abîmer le bord du trou ou distraire celui qui putte. Le plus important est de respecter le choix du joueur et de garder le green en bon état.','Demande au joueur ce qu’il souhaite avant qu’il se prépare. Si le drapeau doit être retiré, attends le bon moment, tiens-le sans gêner et pose-le hors des lignes utiles. Replace-le verticalement et doucement quand le groupe a terminé, sans appuyer sur le bord du trou.','Retirer le drapeau au dernier instant sans prévenir ou le laisser tomber contre le trou. Ces gestes peuvent perturber le coup et marquer le green.','Quand le groupe en a besoin, retire puis replace soigneusement le drapeau avec l’accord des partenaires.','Fais répéter la coordination verbale avant le putt et le geste de remise en place sans balle, puis laisse les juniors agir en situation.','R&A, Règles de golf, règle 13.2','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
