insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Garder le silence au bon moment','Un partenaire commence sa routine avant un coup important. Ton téléphone vibre et tu racontes encore le trou précédent.','Le golf reste un jeu social : il n’est pas nécessaire de se taire pendant toute la partie. Mais au moment où quelqu’un prépare et joue son coup, une voix, une sonnerie ou un bruit de fermeture de sac peut casser sa concentration. Tenir compte de l’autre aide le groupe à jouer dans de bonnes conditions.','Mets ton téléphone en mode adapté à l’activité. Termine la conversation avant la routine du joueur, immobilise ton matériel et attends la fin de son coup pour reprendre. Si tu dois traiter une urgence, éloigne-toi dans une zone sûre et préviens le groupe.','Penser que parler doucement juste derrière le joueur ne le dérange pas, ou commencer à ranger des clubs pendant qu’il vise.','Pendant les coups de ton groupe, prépare un environnement calme : téléphone discret, matériel immobile et conversations au bon moment.','Fais écouter au groupe quelques bruits ordinaires de matériel et demande lesquels sont gênants pendant une routine de coup.','R&A, Règles de golf, règle 1.2a, considération envers les autres','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
