insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Bien se placer','Tu es à distance de sécurité, mais ton ombre traverse la zone où un partenaire veut putter. Tu changes de place pendant qu’il vise.','Être hors de danger ne suffit pas toujours pour respecter la concentration des autres. Un mouvement dans le champ de vision, une ombre qui bouge ou une présence directement derrière le joueur peuvent le distraire. Cette fiche complète la vérification de sécurité : elle concerne surtout le confort visuel et le calme du joueur.','Avant sa routine, observe la lumière et la direction du coup. Mets-toi sur le côté, à une distance confortable, puis reste immobile jusqu’à la fin. Si le partenaire te demande de bouger, fais-le avant qu’il reprenne sa préparation.','Se déplacer lentement pendant le backswing en croyant que cela ne se voit pas. Même sans bruit, le mouvement peut gêner.','Demande à un partenaire si l’emplacement choisi le gêne et ajuste-toi avant qu’il joue.','Place les juniors à plusieurs endroits sûrs et demande au joueur de décrire ce qu’il voit. Fais corriger avant le coup, sans humilier celui qui s’est trompé.','R&A, Règles de golf, règle 1.2a, considération envers les autres','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
