insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Encourager sans distraire','Une partenaire vient de rater un putt. Tu veux l’aider, mais elle se prépare déjà à jouer le coup suivant.','Un encouragement peut soutenir le groupe s’il arrive au bon moment et respecte la personne. Pendant la préparation d’un coup, même un compliment peut distraire. En compétition, indiquer un club ou une stratégie peut aussi constituer un conseil au sens de la Règle 10.2 ; un mot de soutien général est différent d’une instruction technique.','Attends que le coup soit terminé et que la joueuse soit disponible. Dis quelque chose de simple et sincère, comme « bien récupéré » ou « on continue ». Évite de commenter chaque geste. Garde les conseils techniques pour les moments et les formats où ils sont autorisés.','Donner une consigne de jeu non demandée au moment du swing ou affirmer qu’un encouragement ordinaire est toujours un conseil interdit.','Après un coup, adresse un encouragement simple à un partenaire et observe s’il le reçoit bien.','Mets en scène des phrases de soutien et des consignes techniques ; demande au groupe de repérer la différence selon le contexte de jeu.','R&A, Règles de golf, règles 1.2a et 10.2a','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
from public.etiquette_cards where stable_key='08.3'
on conflict (card_id,version,locale) do nothing;
