insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Respecter les zones protégées','Ta balle semble avoir franchi une corde qui protège une zone humide. Tu pourrais la récupérer en quelques pas si tu passais sous la corde.','Une zone signalée peut protéger la nature, une partie fragile du parcours ou les personnes. La corde ou le panneau fixe une limite d’accès qu’il faut respecter, même si la balle est visible. La procédure de jeu dépend de la façon dont cette zone est définie dans les règles locales et les consignes du jour.','Reste hors de la zone. Lis la signalétique et appelle le coach ou la personne compétente pour savoir comment poursuivre le jeu. Accepte de laisser la balle si l’accès est interdit. Réfléchis à ce que la protection permet de préserver avant de passer au coup suivant.','Entrer rapidement parce que « personne ne regarde », ou appliquer de mémoire une procédure de dégagement qui ne correspond pas à cette zone.','Identifie une zone protégée de ton club, puis explique à quoi sert l’interdiction d’y entrer.','Présente la signalétique réelle du club et fais distinguer la restriction d’accès de la procédure de jeu éventuellement prévue par la règle locale.','Règles locales et consignes de protection du club','Consignes locales du club à vérifier pour chaque partie','club_guidance'
from public.etiquette_cards where stable_key='09.1'
on conflict (card_id,version,locale) do nothing;
