insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Bien utiliser son sac et son chariot','Tu arrives près d’un green avec ton chariot. Le prochain départ se trouve derrière le green, mais tu laisses ton matériel devant l’entrée.','Un sac posé au mauvais endroit peut gêner les putts, bloquer le passage ou obliger le groupe à revenir sur ses pas. Certains clubs interdisent les chariots sur le green, les départs ou des zones humides. Bien préparer sa sortie aide le rythme sans sacrifier le soin du terrain.','Avant de rejoindre ta balle, repère le chemin autorisé vers le départ suivant. Place ton sac ou ton chariot à l’extérieur des zones interdites, du côté de la sortie, sans couper la trajectoire d’un autre joueur. En repartant, vérifie que tu n’as rien laissé.','Traverser le green avec le chariot parce que le prochain départ paraît proche, ou laisser le sac sur la route des autres groupes.','Sur un trou, place ton matériel vers le prochain départ dans une zone autorisée et observe si le départ du green devient plus simple.','Montre les cheminements locaux et demande au junior de choisir un emplacement qui respecte à la fois le terrain et le jeu du groupe.','Consignes de circulation et d’entretien du club','Consignes locales du club à vérifier pour chaque partie','club_guidance'
from public.etiquette_cards where stable_key='09.2'
on conflict (card_id,version,locale) do nothing;
