insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Ne laisser aucun déchet','Après une collation, ton emballage glisse d’une poche du sac. Plus loin, tu vois aussi un objet inconnu près du chemin.','Un parcours propre est plus agréable et plus sûr pour les joueurs, le personnel et les animaux. Garder ses propres déchets est une responsabilité simple. Ramasser un objet inconnu n’est pas toujours une bonne idée : il peut être coupant, sale ou dangereux. Savoir demander de l’aide fait aussi partie du soin du terrain.','Garde tes emballages et petits déchets dans une poche fermée jusqu’à une poubelle. Avant de quitter une zone, regarde autour de ton sac. Si tu vois un objet inconnu ou potentiellement dangereux, ne le touche pas et signale-le à un adulte ou au personnel du club.','Laisser un petit déchet en se disant que le vent ou l’équipe d’entretien s’en chargera, ou toucher sans précaution un objet suspect.','Repars avec tous tes déchets ; pour un objet inconnu, coupant ou dangereux, demande de l’aide au lieu de le ramasser.','Prévois une poche à déchets dans le sac de démonstration et explique les cas dans lesquels un junior doit seulement signaler un objet.','R&A, Règles de golf, règle 1.2a, soin du parcours ; consignes du club','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','good_practice'
from public.etiquette_cards where stable_key='09.3'
on conflict (card_id,version,locale) do nothing;
