insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Respecter partenaires et adversaires','Tu arrives à une compétition et rejoins des joueurs que tu ne connais pas. Plus tard, un score serré rend les échanges tendus.','Un groupe joue mieux quand chacun connaît les autres et communique clairement. Le respect ne dépend ni du score ni de la formule : il vaut pour les partenaires comme pour les adversaires. Tu peux exprimer un doute sur un fait ou une règle sans attaquer la personne. Les conditions de compétition peuvent aussi comporter un code de conduite précis.','Présente-toi avant le départ, écoute les noms et annonce clairement les informations nécessaires au jeu. En cas de désaccord, décris ce que tu as vu, laisse l’autre répondre et sollicite la personne compétente si besoin. Termine les échanges avec la même courtoisie que tu souhaites recevoir.','Faire une remarque blessante sous pression ou supposer qu’un adversaire cherche à tricher simplement parce qu’il a une autre lecture de la situation.','Commence ta prochaine partie par une présentation cordiale à chaque personne du groupe.','Fais répéter un désaccord factuel en deux versions, l’une accusatrice et l’autre précise et respectueuse ; discute de leurs effets.','R&A, Règles de golf, règle 1.2a','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
from public.etiquette_cards where stable_key='10.1'
