insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Demander de l’aide en cas de doute','Une balle repose près d’une zone marquée et ton groupe hésite sur la bonne procédure. Personne n’est entièrement sûr de la limite.','Inventer une réponse rapide peut mener à jouer du mauvais endroit ou à enregistrer un score incorrect. Une bonne question de règle commence par les faits : où est la balle, quelle formule se joue, quels marquages sont visibles et que s’est-il passé ? En compétition, les procédures de la Règle 20 permettent de demander une décision selon le contexte.','Arrête-toi avant d’agir sur la balle. Décris la situation sans suggérer la réponse qui t’arrange, puis contacte le coach, l’arbitre ou le comité selon l’activité. Note les faits utiles. Si le jeu doit continuer, suis la procédure indiquée par la personne compétente.','Déplacer la balle d’abord puis demander ensuite si c’était permis. Les faits deviennent plus difficiles à vérifier.','À partir d’une situation d’entraînement, formule une question de règle avec les faits nécessaires et le bon interlocuteur.','Prépare un cas incomplet et fais demander aux juniors les informations manquantes avant de proposer une décision.','R&A, Règles de golf, règle 20','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
