insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Comprendre le code de conduite','Le règlement de ton tournoi mentionne un code de conduite. Tu te demandes si toutes les recommandations habituelles du club entraînent automatiquement une pénalité.','La Règle 1.2 décrit un comportement attendu de tous les joueurs. Un comité peut aussi adopter un code de conduite pour une compétition et définir des pénalités pour des manquements précis. Une recommandation générale de politesse n’est donc pas automatiquement une infraction pénalisée. Lire le document du tournoi évite de confondre ces niveaux.','Avant le départ, repère le code applicable, ses exemples concrets et la personne qui répond aux questions. Si un incident survient, explique les faits et demande comment le code s’applique. Continue à respecter les autres même quand aucun barème de pénalité n’est prévu.','Attribuer une pénalité à toute maladresse d’étiquette, ou croire qu’un code écrit remplace toutes les Règles de golf.','Repère où trouver le code de conduite de ton club ou d’un tournoi, puis cite une règle de comportement qu’il prévoit réellement.','Compare une attente générale de la Règle 1.2a avec une disposition d’un code de conduite local, sans inventer de sanction.','R&A, Règles de golf, règle 1.2b','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','code'
from public.etiquette_cards where stable_key='10.3'
on conflict (card_id,version,locale) do nothing;
