insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Féliciter les autres','Un partenaire réussit un coup difficile alors que tu viens de perdre un trou. Tu ressens d’abord ta propre déception.','Reconnaître un beau geste ou un effort ne retire rien à ton envie de bien jouer. Un mot juste peut rendre la partie plus agréable, surtout quand le résultat est serré. Il n’est pas nécessaire d’en faire trop ni de prétendre que tu n’es pas déçu. La sincérité compte davantage qu’une formule automatique.','Attends que le coup soit terminé et que le joueur soit disponible. Félicite un élément précis si tu l’as remarqué : le choix prudent, la récupération ou le putt réussi. Après une victoire, laisse aussi à l’autre le temps de digérer son résultat.','Rester muet uniquement parce que l’autre a gagné, ou multiplier les compliments ironiques qui ressemblent à des reproches.','Félicite sincèrement un autre joueur pour un effort, un beau coup ou une victoire que tu as observés.','Invite les juniors à distinguer un compliment précis d’une formule de politesse forcée, puis respecte leur manière naturelle de s’exprimer.','R&A, Règles de golf, règle 1.2a ; conseil pédagogique ActiviTee','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','good_practice'
from public.etiquette_cards where stable_key='11.1'
on conflict (card_id,version,locale) do nothing;
