insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Maîtriser ses émotions','La partie se termine et ton score est bien moins bon que prévu. Tu as envie de dire que tout a été raté.','Un résultat final mélange beaucoup de coups, de décisions et de circonstances. Il peut être décevant sans résumer toute ta journée. Prendre du recul aide à apprendre et à parler aux autres avec respect. Cette étape concerne l’après-partie ; elle est différente du réflexe de sécurité immédiatement après un mauvais coup.','Éloigne-toi un instant du score si nécessaire, puis nomme honnêtement ce que tu ressens. Choisis un point qui a fonctionné et un objectif concret pour la prochaine séance. Si la frustration reste forte, demande à ton coach un échange au calme avant de juger ton jeu.','Décharger sa déception sur un partenaire, un arbitre ou un bénévole, ou conclure qu’une seule carte définit ton niveau.','Après la partie, note un point positif précis et un objectif simple que tu aimerais travailler.','Fais un débrief bref qui sépare résultat, émotions et comportement ; laisse au junior le choix de partager ou non son ressenti au groupe.','R&A, Règles de golf, règle 1.2a ; conseil pédagogique ActiviTee','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','good_practice'
