insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Respecter arbitres, coaches et bénévoles','Une décision d’arbitrage ne te plaît pas. Un bénévole te demande en même temps de libérer une zone pour le groupe suivant.','Ces personnes contribuent à la sécurité et au bon déroulement de l’activité. Tu peux demander une explication sur une décision sans hausser le ton ni couper la parole. Écouter d’abord permet de comprendre la situation ; remercier reconnaît le travail souvent invisible derrière une partie ou un tournoi.','Laisse la personne terminer, reformule ce que tu as compris et pose une question factuelle si un point reste obscur. Suis les indications de sécurité sans attendre. À la fin, remercie au moins une personne pour une aide concrète, même si ton résultat t’a déçu.','Confondre désaccord et manque de respect, ou ignorer une consigne parce qu’elle vient d’un bénévole plutôt que d’un arbitre.','Remercie une personne qui a contribué au déroulement de ta prochaine activité et précise ce que son aide a permis.','Joue une demande d’explication calme après une décision difficile ; laisse les juniors pratiquer une question précise et une réponse respectueuse.','R&A, Règles de golf, règle 1.2a ; code de conduite applicable le cas échéant','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','good_practice'
from public.etiquette_cards where stable_key='11.3'
on conflict (card_id,version,locale) do nothing;
