insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','La checklist avant la partie','Demain, tu joues sur un parcours que tu connais peu. Tu as l’horaire du départ, mais tu n’as pas encore vérifié la météo ni les consignes du jour.','L’autonomie commence avant le premier coup. Préparer séparément le matériel, l’heure, la formule et les consignes réduit les oublis. Une checklist personnelle fonctionne mieux qu’une liste interminable copiée : elle doit te permettre de trouver en quelques secondes ce qui manque encore.','La veille, note ton heure d’arrivée et le lieu du départ. Vérifie la formule de jeu, l’équipement nécessaire et les consignes locales. Prépare ton sac, puis garde une petite marge pour un changement de météo ou de trajet. Demande au coach ce qui reste flou avant le départ.','Cocher « matériel prêt » alors que tu n’as pas vérifié les objets essentiels, ou penser que connaître le parcours dispense de lire les consignes actualisées.','Prépare ta prochaine partie avec une checklist personnelle de quelques points et révise-la après usage.','Laisse le junior choisir ses rubriques ; vérifie seulement que sécurité, horaire, matériel, formule et consignes sont couverts.','R&A, Règles de golf, règles 5.3a et 1.3a ; bonne pratique ActiviTee','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','good_practice'
from public.etiquette_cards where stable_key='12.1'
