insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Les bons réflexes pendant le tour','Au milieu de la partie, tu dois à la fois jouer ton prochain coup, laisser passer un partenaire et prendre soin d’une trace sur le terrain.','Les bons réflexes ne sont pas une suite de tâches à faire toutes en même temps. Sécurité d’abord, puis respect des autres, rythme du groupe et soin du parcours au moment adapté. Selon la situation, tu attends avant de réparer une trace pour ne pas modifier les conditions d’un coup encore à jouer. Savoir choisir l’ordre des gestes montre une vraie autonomie.','Avant chaque coup, vérifie la zone. Pendant l’attente, prépare ta décision sans gêner. Après ton coup et lorsque c’est permis, prends soin de la surface utilisée. Entre les coups, avance avec ton groupe. Si deux exigences semblent se contredire, arrête-toi et demande au coach.','Vouloir aller vite au point de jouer sans vérifier la sécurité, ou réparer immédiatement une zone proche d’une balle encore en jeu.','Sur trois trous, choisis un réflexe de sécurité, un de respect, un de rythme et un de soin du parcours, puis essaie de les appliquer.','Observe des situations réelles et invite le junior à expliquer l’ordre de ses décisions sans transformer la mission en contrôle obligatoire.','R&A, Règles de golf, règles 1.2a, 5.6b et 8 ; bonne pratique ActiviTee','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','good_practice'
from public.etiquette_cards where stable_key='12.2'
