insert into public.etiquette_card_versions(card_id,version,locale,title,situation,simple_explanation,action_text,common_mistake,mission_text,coach_tip,official_reference,reference_version,reference_kind)
select id,1,'fr','Après la partie','Tu as terminé le dernier trou. Le groupe se dirige vers le club-house, mais ta carte n’est pas encore vérifiée et ton matériel reste dispersé.','La fin du jeu comporte encore des gestes utiles. En stroke play, les obligations de la carte de score et de sa remise dépendent du cadre de compétition ; il faut suivre les instructions du comité. Remercier les autres et ranger son matériel font partie d’une fin de partie respectueuse. Un bref bilan aide à retenir une chose apprise sans réduire la journée au résultat.','Avant de te disperser, vérifie les scores et les formalités demandées pour ta formule. Remercie le groupe, récupère tous tes objets et laisse l’espace propre. Une fois au calme, note un moment réussi et une question à poser lors de la prochaine séance.','Partir sans vérifier la carte en compétition, oublier ses affaires près du green ou transformer le débrief en liste de reproches.','Réalise ta routine de fin de partie, avec l’aide adaptée à ton autonomie : score, remerciements, matériel et bref bilan.','Montre la procédure de remise de carte propre à l’épreuve et laisse le junior faire seul les étapes qu’il maîtrise déjà.','R&A, Règles de golf, règle 3.3b ; conditions de compétition du comité','R&A, Règles de golf en vigueur depuis 2023 ; vérification éditoriale requise','rule'
from public.etiquette_cards where stable_key='12.3'
